pub fn canOfferH2(self: HTTPClient) bool {
        if (self.flags.force_http1) {
            return false;
        }
        if ((self.http_proxy != null)) {
            return false;
        }
        if (self.flags.is_preconnect_only) {
            return false;
        }
        if ((self.unix_socket_path.length() > 0)) {
            return false;
        }
        if ((self.state.original_request_body == .sendfile)) {
            return false;
        }
        return ((self.flags.force_http2 or experimental_http2_client_from_cli) or bun.feature_flag.BUN_FEATURE_FLAG_EXPERIMENTAL_HTTP2_CLIENT.get());
}

pub fn alpnOffer(self: HTTPClient) bun.BoringSSL.c.SSL.AlpnOffer {
        if ((!self.canOfferH2())) {
            return .h1;
        }
        if (self.flags.force_http2) {
            return .h2_only;
        }
        return .h1_or_h2;
}

pub fn canTryH3AltSvc(self: HTTPClient) bool {
        if ((self.flags.force_http1 or self.flags.force_http2)) {
            return false;
        }
        if ((self.http_proxy != null)) {
            return false;
        }
        if (self.flags.is_preconnect_only) {
            return false;
        }
        if ((self.unix_socket_path.length() > 0)) {
            return false;
        }
        if ((self.state.original_request_body == .sendfile)) {
            return false;
        }
        return h3AltSvcEnabled();
}

